9	// requireInvalidContinuation pins the public contract for a continuation
10	// whose filter no longer matches the first page: it is an argument problem,
11	// never a chain-data problem, and no page results are observable.
12	func requireInvalidContinuation(t *testing.T, index *Index, query TxQuery) {
