27	// set of identifiers matters: reordered, deduplicated or re-duplicated
28	// spellings describe the same filter and must keep working with the original
29	// cursor. Every occurrence survives (including repeats inside one block), in
30	// height/position order, and whole-range statistics stay fixed.
31	func TestQueryTxsFilterSetSpellingAcrossPages(t *testing.T) {
