159		}
160		if !reflect.DeepEqual(emptyFirst.Hits, emptyIDOnly[:1]) || emptyFirst.TotalMatches != 2 || emptyFirst.MatchedBlocks != 2 {
161			t.Fatalf("unexpected empty-id first page: %+v", emptyFirst)
162		}
