254		// query with the wider set matches exactly the same transactions; the
255		// continuation must still be rejected as a condition change.
256		withAbsent, err := index.QueryTxs(TxQuery{TxIDs: []string{"a", "b", "z"}, PageSize: MaxPageSize})
257		if err != nil {
